INSERT INTO products VALUES(2,'laptop','MacBook Neo adalah laptop pemula (entry-level) terjangkau dari Apple berbobot 1,23 kg. Laptop ini mengandalkan chip A18 Pro, layar Liquid Retina 13 inci (500 nit), serta baterai tahan hingga 16 jam, menjadikannya pilihan ekonomis berbalut bodi aluminium kokoh untuk tugas harian.',14000014,'products/DbPNp9sC0ZBXUonpqg6zx1iFHElae54k1aKdoj6T.webp','2026-08-22 10:24:28','2026-08-22 10:24:28');
CREATE TABLE IF NOT EXISTS "galleries" ("id" integer primary key autoincrement not null, "title" varchar not null, "image" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime);
